import WelcomeStorageKeys from '../constants/storage-keys';

/**
 * Generates the storage key for tracking the expanded state of the Wayfinder setup section in the welcome page.
 * The key is generated by replacing the `{{productName}}` placeholder in the `WelcomeStorageKeys.WAYFINDER_SETUP_EXPANDED`
 * template with the lowercase version of the provided product name.
 * @param productName
 * @returns {string} The storage key for tracking the Wayfinder setup section expanded state.
 */
export default function getWayfinderSetupExpandedStorageKey(productName: string): string {
  return WelcomeStorageKeys.WAYFINDER_SETUP_EXPANDED.replace('{{productName}}', productName.toLowerCase());
}
